--- /dev/null
+++ b/installer/19BK.nix
@@ -0,0 +1,36 @@
+# generated by nixin — edit state.json or use the CLI
+{
+  config,
+  lib,
+  pkgs,
+  ...
+}:
+let
+  # nixpkgs 3ec6363 (2026-10-23), as flake.lock had it when the pin was made; the same tree the flake input had
+  nixpkgs-3ec6363 = import (
+    builtins.fetchTarball {
+      url = "https://github.com/NixOS/nixpkgs/archive/3ec636362e1816bc2f0888fa0fa2c69f1bc9e504.tar.gz";
+      sha256 = "sha256-rZLrzrC6i+jnTAlvPZHogKDulY7WWDEv9hJeHieO7Zw=";
+    }
+  );
+in
+{
+  nixpkgs.overlays = [
+    (
+      final: prev:
+      # never the module's `pkgs` here: it depends on these overlays
+      let
+        pinned = nixpkgs-3ec6363 {
+          inherit (prev.stdenv.hostPlatform) system;
+          config = config.nixpkgs.config;
+          overlays = [ ];
+        };
+      in
+      {
+        # pin "kernel" (2026-11-05): linux_7_2 held at 7.2.12 — T2 kernel build takes 2-3 h. `nixin unpin kernel`
+        linux_7_2 = pinned.linux_7_2;
+        linuxPackages_7_2 = final.linuxPackagesFor final.linux_7_2;
+      }
+    )
+  ];
+}
